package com.optilink.optical;

import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Objects;

/**
 * Text envelope used to carry arbitrary protocol bytes inside QR byte-mode content.
 */
public final class QrPayloadEnvelope {
    /**
     * Versioned prefix for QR payloads generated by OptiLink.
     */
    public static final String PREFIX = "OPTL1:";

    private QrPayloadEnvelope() {
    }

    /**
     * Encodes binary frame bytes as a versioned QR text payload.
     *
     * @param frameBytes canonical protocol frame bytes
     * @return QR text content
     */
    public static String encode(byte[] frameBytes) {
        Objects.requireNonNull(frameBytes, "frameBytes");
        return PREFIX + Base64.getUrlEncoder().withoutPadding().encodeToString(frameBytes.clone());
    }

    /**
     * Decodes QR text content into binary frame bytes.
     *
     * @param envelope QR text content
     * @return decoded frame bytes
     */
    public static byte[] decode(String envelope) {
        Objects.requireNonNull(envelope, "envelope");
        if (!envelope.startsWith(PREFIX)) {
            throw new IllegalArgumentException("QR payload is not an OptiLink envelope");
        }
        String payload = envelope.substring(PREFIX.length());
        return Base64.getUrlDecoder().decode(payload.getBytes(StandardCharsets.US_ASCII));
    }
}
